INSERT INTO `sys_system_config` VALUES (1,'monitor.sample.interval.seconds','60','指标采样间隔（秒）','monitor','int','60','系统指标落库频率，改小更精确但数据量更大',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(2,'monitor.retention.detail.days','7','明细数据保留天数','monitor','int','7','sys_metric_sample 保留天数',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(3,'monitor.retention.hourly.days','90','小时聚合保留天数','monitor','int','90','sys_metric_hourly 保留天数',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(4,'monitor.online.idle.minutes','5','在线判定活跃窗口（分钟）','monitor','int','5','最近N分钟内有活动即视为在线',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(5,'monitor.api.slow.threshold.ms','1000','慢接口阈值（毫秒）','monitor','int','1000','接口耗时超过该值计入慢接口统计',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(6,'monitor.quota.warn.percent','80','额度预警阈值（%）','monitor','int','80','用量占比达到该值标黄',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(7,'monitor.quota.danger.percent','95','额度告警阈值（%）','monitor','int','95','用量占比达到该值标红',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(8,'monitor.task.enabled','1','启用监控定时任务','monitor','bool','1','关闭后不再采样与清理',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(9,'tenant.expire.warn.days','30','到期预警天数','tenant','int','30','距到期N天内列入预警名单',1,'2026-08-31 08:58:10','2026-08-31 08:58:10'),(10,'tenant.stats.retention.months','12','租户月度快照保留月数','tenant','int','12','超过该月数的历史快照自动清理',1,'2026-08-31 08:58:10','2026-08-31 08:58:10');
